SELECT shipped_cohort, cost_count, row_count FROM (SELECT CASE WHEN YEAR(shipped_date) < 2024 THEN 'before_2024' WHEN YEAR(shipped_date) = 2024 THEN '2024' ELSE 'after_2024' END shipped_cohort, COUNT(cost) cost_count, COUNT(*) row_count FROM shipments GROUP BY CASE WHEN YEAR(shipped_date) < 2024 THEN 'before_2024' WHEN YEAR(shipped_date) = 2024 THEN '2024' ELSE 'after_2024' END) t WHERE cost_count < 4 ORDER BY cost_count
